checks.addition:
for a in range(-4, 5):
    for b in range(-4, 5):
        self.assertEqual(solve(a, b), a + b)

checks.chunks:
for size in range(1, 10):
    values = list(range(7))
    self.assertEqual(solve(values, size), [values[i:i + size] for i in range(0, 7, size)])

checks.inclusive-range:
for start in range(-3, 4):
    for stop in range(-3, 4):
        self.assertEqual(solve(start, stop), list(range(start, stop + 1)))

checks.capped-backoff:
for base in (1, 3, 5):
    for attempt in range(5):
        for cap in (4, 100):
            with self.subTest(base=base, attempt=attempt, cap=cap):
                self.assertEqual(solve(base, attempt, cap), min(base * 2 ** attempt, cap))

checks.pagination-contract:
for length in range(10):
    for page in range(1, 6):
        for size in range(1, 5):
            values = list(range(length))
            self.assertEqual(response(values, page, size), {'items': values[(page - 1) * size:page * size], 'has_next': page * size < length})
self.assertRaises(ValueError, paginate, [], 1, 0)

checks.retry-contract:
for status in (200, 400, 404, 429, 500, 501, 502, 503, 504, 599, 600):
    with self.subTest(status=status):
        self.assertEqual(retryable(status), status == 429 or 500 <= status < 600)
for base in (2, 3, 5):
    for attempt in range(5):
        with self.subTest(base=base, attempt=attempt):
            self.assertEqual(next_delay(503, attempt, base, 100), min(base * 2 ** attempt, 100))
